CREATE TABLE public.identity_pairs (user_id uuid PRIMARY KEY, email text NOT NULL, original_wallet text NOT NULL, current_wallet text NOT NULL, bound_at timestamptz NOT NULL DEFAULT now(), recovery_used boolean NOT NULL DEFAULT false);
GRANT ALL ON public.identity_pairs TO service_role;
ALTER TABLE public.identity_pairs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.identity_wallet_history (wallet text PRIMARY KEY, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.identity_wallet_history TO service_role;
ALTER TABLE public.identity_wallet_history ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.identity_review_cases (user_id uuid PRIMARY KEY, category text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.identity_review_cases TO service_role;
ALTER TABLE public.identity_review_cases ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.identity_recovery_grants (user_id uuid PRIMARY KEY, target_wallet text NOT NULL, reason text NOT NULL, ownership_evidence text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), actor_id uuid NOT NULL, revoked_at timestamptz, consumed_at timestamptz);
GRANT ALL ON public.identity_recovery_grants TO service_role;
ALTER TABLE public.identity_recovery_grants ENABLE ROW LEVEL SECURITY;
INSERT INTO public.identity_review_cases(user_id,category) SELECT p.id,'INCOMPATIBLE_EXISTING_PAIR' FROM public.profiles p LEFT JOIN auth.users u ON u.id=p.id WHERE p.wallet_address IS NOT NULL AND (p.wallet_address !~* '^0x[a-f0-9]{40}$' OR u.email_confirmed_at IS NULL OR lower(u.email) IS DISTINCT FROM lower(p.email) OR EXISTS(SELECT 1 FROM public.profiles q WHERE q.id<>p.id AND lower(q.wallet_address)=lower(p.wallet_address)));
INSERT INTO public.identity_pairs(user_id,email,original_wallet,current_wallet,bound_at) SELECT id,lower(email),lower(wallet_address),lower(wallet_address),coalesce(last_binding_change,created_at) FROM public.profiles WHERE wallet_address IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.identity_review_cases c WHERE c.user_id=profiles.id);
INSERT INTO public.identity_wallet_history(wallet,user_id) SELECT current_wallet,user_id FROM public.identity_pairs;
CREATE FUNCTION public.guard_permanent_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pair public.identity_pairs; BEGIN SELECT * INTO pair FROM public.identity_pairs WHERE user_id=NEW.id; IF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Identity account is immutable'; END IF; IF FOUND AND (lower(NEW.email) IS DISTINCT FROM pair.email OR lower(NEW.wallet_address) IS DISTINCT FROM pair.current_wallet) THEN RAISE EXCEPTION 'Verified email and wallet identity is permanent; approved recovery required'; END IF; IF NOT FOUND AND NEW.wallet_address IS NOT NULL AND (TG_OP='INSERT' OR NEW.wallet_address IS DISTINCT FROM OLD.wallet_address) THEN RAISE EXCEPTION 'First binding requires verified identity transaction'; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_guard_permanent_identity BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_permanent_identity();
CREATE FUNCTION public.set_identity_recovery(p_actor uuid,p_wallet text,p_user uuid,p_target text,p_reason text,p_evidence text,p_expiry timestamptz,p_revoke boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pair public.identity_pairs; old_grant jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.app_admins a ON lower(p.email)=a.email JOIN auth.users u ON u.id=p.id WHERE p.id=p_actor AND lower(p.wallet_address)=lower(p_wallet) AND a.role='super_admin' AND NOT a.disabled AND u.email_confirmed_at IS NOT NULL AND lower(u.email)=lower(p.email)) THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO pair FROM public.identity_pairs WHERE user_id=p_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Bound identity required; review incompatible accounts separately'; END IF; SELECT to_jsonb(g) INTO old_grant FROM public.identity_recovery_grants g WHERE user_id=p_user; IF p_revoke THEN UPDATE public.identity_recovery_grants SET revoked_at=now() WHERE user_id=p_user AND consumed_at IS NULL; ELSE IF pair.recovery_used THEN RAISE EXCEPTION 'One recovery maximum'; END IF; IF lower(p_target) !~ '^0x[a-f0-9]{40}$' OR lower(p_target)=pair.current_wallet THEN RAISE EXCEPTION 'Different valid target wallet required'; END IF; IF length(trim(p_reason)) NOT BETWEEN 10 AND 500 OR length(trim(p_evidence)) NOT BETWEEN 10 AND 500 THEN RAISE EXCEPTION 'Ownership verification and reason required'; END IF; IF p_expiry<=now() OR p_expiry>now()+interval '24 hours' THEN RAISE EXCEPTION 'Expiry must be within 24 hours'; END IF; IF EXISTS(SELECT 1 FROM public.identity_wallet_history WHERE wallet=lower(p_target) AND user_id<>p_user) OR EXISTS(SELECT 1 FROM public.profiles WHERE lower(wallet_address)=lower(p_target) AND id<>p_user) THEN RAISE EXCEPTION 'Wallet unavailable'; END IF; INSERT INTO public.identity_recovery_grants(user_id,target_wallet,reason,ownership_evidence,expires_at,actor_id) VALUES(p_user,lower(p_target),trim(p_reason),trim(p_evidence),p_expiry,p_actor) ON CONFLICT(user_id) DO UPDATE SET target_wallet=excluded.target_wallet,reason=excluded.reason,ownership_evidence=excluded.ownership_evidence,expires_at=excluded.expires_at,actor_id=p_actor,created_at=now(),revoked_at=NULL,consumed_at=NULL; END IF; INSERT INTO public.admin_audit_events(actor_user_id,actor_email,actor_role,object_type,object_id,action,old_value,new_value,reason) SELECT p_actor,p.email,'super_admin','identity_recovery',p_user::text,CASE WHEN p_revoke THEN 'REVOKED' ELSE 'AUTHORIZED' END,old_grant,(SELECT to_jsonb(g) FROM public.identity_recovery_grants g WHERE user_id=p_user),p_reason FROM public.profiles p WHERE p.id=p_actor; END $$;
REVOKE ALL ON FUNCTION public.set_identity_recovery(uuid,text,uuid,text,text,text,timestamptz,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.set_identity_recovery(uuid,text,uuid,text,text,text,timestamptz,boolean) TO service_role;
CREATE FUNCTION public.bind_verified_identity(p_user_id uuid,p_wallet text,p_nonce text DEFAULT NULL) RETURNS public.profiles LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; pair public.identity_pairs; g public.identity_recovery_grants; n public.siwe_nonces; e text; confirmed timestamptz; w text:=lower(trim(p_wallet)); BEGIN IF w !~ '^0x[a-f0-9]{40}$' THEN RAISE EXCEPTION 'Invalid wallet'; END IF; PERFORM pg_advisory_xact_lock(hashtext('identity-wallet:'||w)); SELECT * INTO p FROM public.profiles WHERE id=p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Profile not found'; END IF; SELECT lower(email),email_confirmed_at INTO e,confirmed FROM auth.users WHERE id=p_user_id; IF confirmed IS NULL OR e IS DISTINCT FROM lower(p.email) OR e='' THEN RAISE EXCEPTION 'Verified matching email required'; END IF; IF EXISTS(SELECT 1 FROM public.identity_review_cases WHERE user_id=p_user_id) THEN RAISE EXCEPTION 'Identity requires review'; END IF; IF EXISTS(SELECT 1 FROM public.identity_wallet_history WHERE wallet=w AND user_id<>p_user_id) OR EXISTS(SELECT 1 FROM public.profiles WHERE lower(wallet_address)=w AND id<>p_user_id) THEN RAISE EXCEPTION 'Wallet unavailable'; END IF; SELECT * INTO pair FROM public.identity_pairs WHERE user_id=p_user_id FOR UPDATE; IF p_nonce IS NOT NULL THEN SELECT * INTO n FROM public.siwe_nonces WHERE nonce=p_nonce FOR UPDATE; IF NOT FOUND OR n.used_at IS NOT NULL OR n.expires_at<=now() OR lower(n.wallet_address)<>w THEN RAISE EXCEPTION 'Challenge expired or consumed'; END IF; END IF; IF pair.user_id IS NOT NULL AND pair.current_wallet<>w THEN IF p_nonce IS NULL OR pair.recovery_used THEN RAISE EXCEPTION 'Permanent identity; recovery unavailable'; END IF; SELECT * INTO g FROM public.identity_recovery_grants WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND OR g.revoked_at IS NOT NULL OR g.consumed_at IS NOT NULL OR g.expires_at<=now() OR g.target_wallet<>w OR n.created_at<g.created_at THEN RAISE EXCEPTION 'Approved fresh recovery required'; END IF; UPDATE public.identity_pairs SET current_wallet=w,recovery_used=true WHERE user_id=p_user_id; UPDATE public.identity_recovery_grants SET consumed_at=now() WHERE user_id=p_user_id; INSERT INTO public.admin_audit_events(actor_user_id,actor_role,object_type,object_id,action,old_value,new_value,reason) VALUES(p_user_id,'user','identity_recovery',p_user_id::text,'CONSUMED',to_jsonb(pair),jsonb_build_object('wallet',w),g.reason); ELSIF pair.user_id IS NULL THEN INSERT INTO public.identity_pairs(user_id,email,original_wallet,current_wallet) VALUES(p_user_id,e,w,w); END IF; INSERT INTO public.identity_wallet_history(wallet,user_id) VALUES(w,p_user_id) ON CONFLICT(wallet) DO NOTHING; IF p_nonce IS NOT NULL THEN UPDATE public.siwe_nonces SET used_at=now() WHERE id=n.id; END IF; PERFORM set_config('app.bypass_profile_guard','on',true); UPDATE public.profiles SET wallet_address=w,last_binding_change=CASE WHEN wallet_address IS DISTINCT FROM w THEN now() ELSE last_binding_change END,binding_changes_count=CASE WHEN wallet_address IS DISTINCT FROM w THEN binding_changes_count+1 ELSE binding_changes_count END WHERE id=p_user_id RETURNING * INTO p; RETURN p; END $$;
REVOKE ALL ON FUNCTION public.bind_verified_identity(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.bind_verified_identity(uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_bind_wallet(p_user_id uuid,p_wallet text) RETURNS public.profiles LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.bind_verified_identity(p_user_id,p_wallet,NULL); $$;
REVOKE ALL ON FUNCTION public.admin_bind_wallet(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_bind_wallet(uuid,text) TO service_role;